def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]
    prev_my = history[-2][0] if n >= 2 else 'C'

    opp_c = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
    opp_d = n - opp_c

    w10 = 10 if n >= 10 else n
    recent_d10 = 0
    for i in range(n - w10, n):
        if history[i][1] == 'D':
            recent_d10 += 1

    w20 = 20 if n >= 20 else n
    recent_d20 = 0
    for i in range(n - w20, n):
        if history[i][1] == 'D':
            recent_d20 += 1

    opp_d_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_run += 1
        else:
            break

    mutual_d_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            mutual_d_run += 1
        else:
            break

    cnt_after_d = 0
    good_after_d = 0
    cnt_after_c = 0
    bad_after_c = 0

    start = max(1, n - 20)
    for i in range(start, n):
        if history[i - 1][0] == 'D':
            cnt_after_d += 1
            if history[i][1] == 'C':
                good_after_d += 1
        elif history[i - 1][0] == 'C':
            cnt_after_c += 1
            if history[i][1] == 'D':
                bad_after_c += 1

    cooperative_like = opp_c * 5 >= opp_d * 6
    anti_like = cnt_after_c >= 4 and bad_after_c * 10 >= cnt_after_c * 7
    forgiving_like = recent_d10 <= 2 or anti_like
    forgiving_after_d = cnt_after_d >= 4 and good_after_d * 10 >= cnt_after_d * 7

    if forgiving_after_d and (cooperative_like or anti_like) and forgiving_like:
        return 'D'

    punishes_d = cnt_after_d >= 2 and good_after_d * 2 < cnt_after_d
    if n == 98 and opp_d <= 2 and recent_d10 <= 2 and not punishes_d:
        return 'D'

    if opp_d > opp_c + 3 or recent_d10 >= 7:
        if mutual_d_run >= 4 and opp_c > 0 and recent_d20 <= 12:
            return 'C'
        return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            if opp_c > opp_d and recent_d10 <= 5:
                return 'C'
            if mutual_d_run >= 4 and opp_c > opp_d and recent_d20 <= 14:
                return 'C'
            return 'D'

        if prev_my == 'D' and opp_c > opp_d and opp_d_run <= 2 and recent_d10 <= 6:
            return 'C'
        return 'D'

    return 'C'
